exercises.reference:
_EMPTY = object()
_TOMB = object()

class LinearProbingMap:
    def __init__(self, capacity=8):
        self._keys = [_EMPTY] * capacity
        self._vals = [None] * capacity
        self._live = 0
        self._used = 0

    def __len__(self):
        return self._live

    def _find(self, key):
        """(index of key or None, index where key could be inserted)."""
        cap = len(self._keys)
        i = hash(key) % cap
        first_tomb = None
        while True:
            k = self._keys[i]
            if k is _EMPTY:
                return None, (i if first_tomb is None else first_tomb)
            if k is _TOMB:
                if first_tomb is None:
                    first_tomb = i
            elif k == key:
                return i, i
            i = (i + 1) % cap

    def put(self, key, value):
        found, free = self._find(key)
        if found is not None:
            self._vals[found] = value
            return
        if self._keys[free] is _EMPTY:
            self._used += 1
        self._keys[free] = key
        self._vals[free] = value
        self._live += 1
        if 3 * self._used > 2 * len(self._keys):
            self._rebuild(max(8, 4 * self._live))

    def get(self, key):
        found, _ = self._find(key)
        if found is None:
            raise KeyError(key)
        return self._vals[found]

    def delete(self, key):
        found, _ = self._find(key)
        if found is None:
            raise KeyError(key)
        self._keys[found] = _TOMB
        self._vals[found] = None
        self._live -= 1

    def _rebuild(self, capacity):
        items = [(k, v) for k, v in zip(self._keys, self._vals) if k is not _EMPTY and k is not _TOMB]
        self._keys = [_EMPTY] * capacity
        self._vals = [None] * capacity
        self._live = self._used = 0
        for k, v in items:
            self.put(k, v)

