from math import gcd

class Ratio:
    def __init__(self, num, den):
        if den == 0:
            raise ZeroDivisionError("denominator is zero")
        self.num, self.den = num, den

    def __eq__(self, other):
        return isinstance(other, Ratio) and self.num * other.den == other.num * self.den

    def __repr__(self):
        return f"Ratio({self.num}, {self.den})"

exercises.reference:
from math import gcd

class Ratio:
    def __init__(self, num, den):
        if den == 0:
            raise ZeroDivisionError("denominator is zero")
        self.num, self.den = num, den

    def __eq__(self, other):
        return isinstance(other, Ratio) and self.num * other.den == other.num * self.den

    def __hash__(self):
        g = gcd(self.num, self.den)
        n, d = self.num // g, self.den // g
        if d < 0:
            n, d = -n, -d
        return hash((n, d))

    def __repr__(self):
        return f"Ratio({self.num}, {self.den})"

exercises.solution:
Hash a **canonical form**: the fraction in lowest terms with a positive denominator. Equal ratios have the same canonical form, so they get the same hash.

```python
def __hash__(self):
    g = gcd(self.num, self.den)          # gcd is never 0 here, since den != 0
    n, d = self.num // g, self.den // g
    if d < 0:
        n, d = -n, -d
    return hash((n, d))
```

Check the tricky cases: `Ratio(-1, -2)` reduces to `(-1, -2)` and flips to `(1, 2)`. `Ratio(0, 5)` and `Ratio(0, -3)` reduce to `(0, 1)` and `(0, -1)`, which flips to `(0, 1)`. A function like `return 0` would also be *consistent* with `__eq__`, but it would put every ratio in the same bucket and turn every set of ratios into a list: correct, and slow. The standard library's `fractions.Fraction` stores fractions already normalised this way, and it goes further: it makes `hash(Fraction(1, 2)) == hash(0.5)`, because `Fraction(1, 2) == 0.5` is `True`.
